    22	    !/[\\\s]/u.test(value) &&
    23	    !Array.from(value).some((character) => {
    24	      const code = character.charCodeAt(0);
    25	      return code < 32 || code === 127;
    26	    })
    27	  ) {
    28	    try {
    29	      const url = new URL(value);
    30	      if (url.hostname && !url.username && !url.password)
    31	        return { kind: "link", value: url.href };
    32	    } catch {
    33	      return { kind: "text", value };
    34	    }
    35	  }
    36	  return { kind: "text", value };
    37	}
